"""Interactive API explorer dashboard for eDocAPI applications."""

from __future__ import annotations

import html
import json


def render_dashboard(routes: list[dict], formats: list[str], max_file_size: int) -> str:
    from edocapi import __version__

    version = __version__
    route_rows = "".join(
        "<tr>"
        f'<td><span class="method">{html.escape(", ".join(route["methods"]))}</span></td>'
        f'<td><code>{html.escape(route["path"])}</code></td>'
        f'<td>{html.escape(route["name"])}</td>'
        f'<td><button class="try" data-route="{index}">Try it ↗</button></td></tr>'
        for index, route in enumerate(routes)
    ) or '<tr><td colspan="4" class="empty">No custom routes registered yet.</td></tr>'
    formats_html = "".join(
        f'<span class="format">{html.escape(kind.upper())}</span>' for kind in formats
    )
    size = f"{max_file_size / 1024 / 1024:g} MB"
    route_json = json.dumps(routes).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101411"><title>eDocAPI · API Explorer</title>
<style>
:root{{--bg:#101411;--panel:#171d19;--line:#29332d;--muted:#94a399;--text:#edf5ef;--green:#a8f078;--mint:#6ee7b7;--orange:#ffc078}}
*{{box-sizing:border-box}}body{{margin:0;background:radial-gradient(ellipse at 82% 0%,#24392c 0,transparent 36%),var(--bg);color:var(--text);font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}}a{{color:var(--green);text-decoration:none}}.shell{{max-width:1180px;margin:auto;padding:28px 24px 60px}}header{{display:flex;align-items:center;justify-content:space-between;margin-bottom:58px}}.brand{{display:flex;gap:12px;align-items:center;font-weight:750;font-size:19px}}.mark{{width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,var(--green),var(--mint));color:#102016;display:grid;place-items:center;font-weight:900}}.badge,.format{{border:1px solid var(--line);border-radius:99px;padding:6px 12px;color:var(--muted);font-size:12px}}.hero{{max-width:760px;margin-bottom:34px}}.eyebrow{{color:var(--green);font-size:12px;text-transform:uppercase;font-weight:800;letter-spacing:.15em}}h1{{font-size:clamp(38px,6vw,66px);line-height:1.02;letter-spacing:-.065em;margin:13px 0 17px}}h1 span,.code{{color:var(--green)}}.lead{{color:#aab8ae;font-size:17px;max-width:630px}}.actions{{display:flex;gap:10px;margin-top:24px;flex-wrap:wrap}}.button,.try{{border:1px solid var(--line);border-radius:9px;padding:9px 13px;background:#1d2720;color:var(--text);font-weight:650;cursor:pointer}}.button.primary{{background:var(--green);color:#122014}}.stats{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:32px 0}}.stat,.panel{{background:linear-gradient(145deg,#1a211c,#151a17);border:1px solid var(--line);border-radius:15px}}.stat{{padding:18px 20px}}.stat small,.muted{{color:var(--muted)}}.stat strong{{display:block;font-size:27px;margin-top:4px}}.grid{{display:grid;grid-template-columns:1.15fr .85fr;gap:16px}}.panel{{padding:22px}}.panel h2{{font-size:16px;margin:0 0 12px}}table{{width:100%;border-collapse:collapse;text-align:left}}th{{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.1em}}td,th{{padding:12px 8px;border-bottom:1px solid var(--line)}}td{{font-size:13px}}td code,.code{{font-family:ui-monospace,Consolas,monospace}}.method{{font-size:10px;font-weight:800;color:var(--mint);background:#16352c;padding:4px 7px;border-radius:5px}}.try{{font-size:11px;color:var(--green);padding:6px 9px}}.empty{{color:var(--muted)}}.formats{{display:flex;gap:7px;flex-wrap:wrap;margin:15px 0 24px}}.format{{border-radius:7px;background:#202a23;color:#c4d7c8;padding:5px 9px;font-weight:750}}.codebox{{background:#0e120f;border:1px solid var(--line);border-radius:10px;padding:14px;margin-top:13px;overflow:auto;color:#c5d3c8;font:12px/1.8 ui-monospace,Consolas,monospace}}.span2{{grid-column:1/-1}}.footer{{color:#718078;font-size:12px;margin-top:26px;display:flex;justify-content:space-between;gap:12px}}.explorer{{display:none;position:fixed;inset:0;z-index:5;background:#000b;place-items:center;padding:20px}}.explorer.open{{display:grid}}.dialog{{width:min(760px,100%);max-height:90vh;overflow:auto;background:#171d19;border:1px solid #35433a;border-radius:16px;padding:24px;box-shadow:0 25px 100px #0009}}.dialog-head{{display:flex;justify-content:space-between;gap:16px}}.close{{background:none;border:0;color:var(--muted);font-size:24px;cursor:pointer}}.field{{display:grid;gap:6px;margin:14px 0;color:#b6c4ba;font-size:13px}}.field input{{width:100%;background:#0e120f;border:1px solid var(--line);padding:10px;border-radius:8px;color:var(--text)}}.requestline{{display:flex;gap:10px;align-items:center;margin:18px 0}}.result{{white-space:pre-wrap;word-break:break-word;max-height:300px;overflow:auto}}.send{{background:var(--green);border:0;border-radius:9px;color:#142014;padding:11px 18px;font-weight:800;cursor:pointer}}@media(max-width:760px){{header{{margin-bottom:38px}}.grid{{grid-template-columns:1fr}}.span2{{grid-column:auto}}.shell{{padding:20px 16px 40px}}.route-table{{overflow:auto}}}}
</style></head><body><main class="shell">
<header><div class="brand"><div class="mark">e</div><span>eDocAPI <span class="muted">/ explorer</span></span></div><div class="badge">DOCUMENT API FRAMEWORK · v{html.escape(version)}</div></header>
<section class="hero"><div class="eyebrow">Your document workflow, at a glance</div><h1>Build APIs.<br><span>Move documents.</span></h1><p class="lead">Explore your endpoints, send live requests, and inspect responses from one developer console.</p><div class="actions"><a class="button primary" href="#routes">Explore endpoints ↓</a><a class="button" href="https://github.com/emmanuelemmanueletim/edocApi">Framework docs ↗</a></div></section>
<section class="stats"><div class="stat"><small>Registered routes</small><strong>{len(routes):02d}</strong></div><div class="stat"><small>Supported formats</small><strong>{len(formats):02d}</strong></div><div class="stat"><small>Upload limit</small><strong>{html.escape(size)}</strong></div></section>
<section class="grid"><div class="panel" id="routes"><h2>⌘ &nbsp;Your API routes</h2><p class="muted" style="font-size:13px">Choose an endpoint to try it and view its response.</p><div class="route-table"><table><thead><tr><th>Method</th><th>Path</th><th>Handler</th><th></th></tr></thead><tbody>{route_rows}</tbody></table></div></div>
<div class="panel"><h2>▧ &nbsp;Supported formats</h2><div class="formats">{formats_html}</div><h2>✳ &nbsp;Document toolkit</h2><div class="codebox">to_pdf() · to_text() · to_html()<br>to_images() · extract_text() · info()<br><span style="color:var(--orange)">PDF:</span> compress() · split() · extract_pages()<br>rotate() · Document.merge(files)</div></div>
<div class="panel span2"><h2>⚡ &nbsp;Quick start</h2><div class="codebox">from edocapi import App, Document<br><br>app = App()<br><br>@app.post("/convert")<br>def convert(file):<br>&nbsp;&nbsp;&nbsp;&nbsp;return Document(file).to_pdf()<br><br># Terminal: py -m edocapi.cli.main run --reload</div></div></section>
<footer class="footer"><span>eDocAPI · Simple API for the developer. Powerful document processing underneath.</span><span>Auto-generated from your app configuration</span></footer></main>
<div class="explorer" id="explorer" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog"><div class="dialog-head"><div><div class="eyebrow">API explorer</div><h2 id="dialog-title" style="font-size:24px;margin:6px 0"></h2><p id="dialog-description" class="muted"></p></div><button class="close" id="close" aria-label="Close">×</button></div><div class="requestline"><span id="dialog-method" class="method"></span><code id="dialog-path" class="code"></code></div><form id="request-form"><div id="fields"></div><button class="send" type="submit">Send request</button></form><div id="response-wrap" hidden><h3>Result <span id="response-status" class="muted"></span></h3><details><summary>Show response details</summary><div class="codebox result" id="response-body"></div></details></div></div></div>
<script type="application/json" id="edocapi-routes">{route_json}</script><script>
const routes=JSON.parse(document.getElementById('edocapi-routes').textContent),modal=document.getElementById('explorer');let active=null;
document.querySelectorAll('.try').forEach(button=>button.addEventListener('click',()=>openExplorer(routes[Number(button.dataset.route)])));
function openExplorer(route){{active=route;document.getElementById('dialog-title').textContent=route.name;document.getElementById('dialog-description').textContent=route.description||'Send a request and inspect the endpoint response.';document.getElementById('dialog-method').textContent=route.methods.join(', ');document.getElementById('dialog-path').textContent=route.path;const fields=document.getElementById('fields');fields.replaceChildren();for(const p of route.parameters||[]){{const wrap=document.createElement('label');wrap.className='field';wrap.textContent=['target_size','target_size_value'].includes(p.name)?'Preferred maximum size (optional)':p.name+(p.required?' *':'');let input;if(p.name==='target_unit'){{input=document.createElement('select');for(const unit of ['KB','MB']){{const option=document.createElement('option');option.value=unit;option.textContent=unit;input.appendChild(option)}}input.value='MB'}}else{{input=document.createElement('input');if(p.kind==='upload'){{input.type='file';if(p.multiple)input.multiple=true}}else{{input.type='text';input.placeholder=p.required?'Required value':'Optional value';if(p.required)input.required=true;if(['target_size','target_size_value'].includes(p.name)){{input.type='number';input.min='1';input.placeholder='Enter target size'}}}}}}input.name=p.name;wrap.appendChild(input);fields.appendChild(wrap)}}document.getElementById('response-wrap').hidden=true;modal.classList.add('open')}}
document.getElementById('close').onclick=()=>modal.classList.remove('open');modal.addEventListener('click',e=>{{if(e.target===modal)modal.classList.remove('open')}});document.addEventListener('keydown',e=>{{if(e.key==='Escape')modal.classList.remove('open')}});
document.getElementById('request-form').addEventListener('submit',async e=>{{e.preventDefault();const values=new FormData(e.currentTarget),url=new URL(active.path,location.origin),pathParams=new Set((active.path.match(/{{[^}}]+}}/g)||[]).map(x=>x.slice(1,-1))),upload=[];for(const p of active.parameters||[]){{const v=values.getAll(p.name);if(p.kind==='upload'){{for(const f of v)if(f&&f.size)upload.push([p.name,f])}}else if(v[0]){{if(pathParams.has(p.name))url.pathname=url.pathname.replace('{{'+p.name+'}}',encodeURIComponent(v[0]));else url.searchParams.set(p.name,v[0])}}}}const method=active.methods.includes('GET')?'GET':active.methods.includes('POST')?'POST':active.methods[0],options={{method}};if(upload.length){{const body=new FormData();for(const [key,file]of upload)body.append(key,file,file.name);options.body=body}}document.getElementById('response-wrap').hidden=false;const status=document.getElementById('response-status'),output=document.getElementById('response-body');status.textContent='Sending…';output.textContent='';try{{const response=await fetch(url,options),type=response.headers.get('content-type')||'',body=type.includes('json')?JSON.stringify(await response.json(),null,2):await response.text();status.textContent=response.ok?response.status+' OK':'HTTP '+response.status+' '+response.statusText;output.textContent=body||'(empty response)'}}catch(error){{status.textContent='Request failed';output.textContent=String(error)}}}});
</script></body></html>'''
